/// <summary>
/// MPJ_15907_LiquorAndTobaccoLicence - kavya
/// system query range class extension 
/// </summary>
[ExtensionOf(classStr(SysQueryRangeUtil))]
final class METSysQueryRangeUtil_Extension
{
}

Method.Source:
    /// <summary>
    /// To return type date based on relative day
    /// </summary>
    /// <param name = "relativeDays">To find relative date</param>
    /// <returns>Date based on parameter</returns>
    [QueryRangeFunction]
    public static date METDay(int relativeDays = 0)
    {
        utcdatetime  currentDateTime;

        currentDateTime = DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::getSystemDateTime(), DateTimeUtil::getUserPreferredTimeZone());

        return DateTimeUtil::date(DateTimeUtil::addDays(currentDateTime,relativeDays));
    }

/// <summary>
/// Creates a query string for all dates that are after the specified date.
/// </summary>
/// <param name = "_date">Specified date</param>
/// <returns>A query string representation of all dates that are later than the specified date</returns>
[QueryRangeFunction]
public static str metGreaterThanDate(transDate _date)
{
    return '> ' + SysQuery::value(_date);
}

/// <summary>
/// Creates a query string for all dates that are equal or after the specified date.
/// </summary>
/// <param name = "_date">Specified date</param>
/// <returns>A query string representation of all dates that are equeal or later than the specified date</returns>
[QueryRangeFunction]
public static str metGreaterThanEqualDate(transDate _date)
{
    return '> ' + SysQuery::value(_date-1);
}

/// <summary>
/// Creates a query string for all dates that are before the specified date.
/// </summary>
/// <param name = "_date">Specified date</param>
/// <returns>A query string representation of all dates that are before than the specified date</returns>
[QueryRangeFunction]
public static str metLessThanDate(transDate _date)
{
    return '< ' + SysQuery::value(_date);
}

/// <summary>
/// Creates a query string for all dates that are equal or before the specified date.
/// </summary>
/// <param name = "_date">Specified date</param>
/// <returns>A query string representation of all dates that are equeal or before the specified date</returns>
[QueryRangeFunction]
public static str metLessThanEqualDate(transDate _date)
{
    return '< ' + SysQuery::value(_date+1);
}
